## Auth.js (NextAuth v5) setup

```ts
// auth.ts — shared config
import NextAuth from "next-auth";
import Google from "next-auth/providers/google";
import GitHub from "next-auth/providers/github";

export const { handlers, auth, signIn, signOut } = NextAuth({
  providers: [Google, GitHub],
  callbacks: {
    authorized({ auth, request }) {
      // Return true to allow, false to deny
      return !!auth?.user;
    },
  },
});
```

```ts
// app/api/auth/[...nextauth]/route.ts
import { handlers } from "@/auth";
export const { GET, POST } = handlers;
```

## Protecting routes — middleware

Middleware runs at the edge before any page renders — the right place for broad auth gates:

```ts
// middleware.ts
export { auth as middleware } from "@/auth";

export const config = {
  // Protect everything under /dashboard and /settings
  matcher: ["/dashboard/:path*", "/settings/:path*"],
};
```

Or with custom logic:

```ts
// middleware.ts
import { auth } from "@/auth";
import { NextResponse } from "next/server";

export default auth((req) => {
  if (!req.auth && req.nextUrl.pathname.startsWith("/dashboard")) {
    const loginUrl = new URL("/login", req.url);
    loginUrl.searchParams.set("callbackUrl", req.nextUrl.pathname);
    return NextResponse.redirect(loginUrl);
  }
});
```

## Reading the session in Server Components

```tsx
// app/dashboard/page.tsx
import { auth } from "@/auth";
import { redirect } from "next/navigation";

export default async function DashboardPage() {
  const session = await auth();

  if (!session?.user) redirect("/login");

  return (
    <div>
      <h1>Welcome, {session.user.name}</h1>
    </div>
  );
}
```

## Sign in / sign out from Client Components

```tsx
"use client";
import { signIn, signOut } from "next-auth/react";

export function AuthButtons() {
  return (
    <div className="flex gap-2">
      <button onClick={() => signIn("google")}>Sign in with Google</button>
      <button onClick={() => signOut()}>Sign out</button>
    </div>
  );
}
```

## Session in Client Components

```tsx
"use client";
import { useSession } from "next-auth/react";

export function Avatar() {
  const { data: session, status } = useSession();

  if (status === "loading") return <AvatarSkeleton />;
  if (!session) return null;

  return <img src={session.user?.image ?? "/default-avatar.png"} alt="" />;
}
```

Wrap the root layout in a `<SessionProvider>` from `next-auth/react` to enable `useSession`:

```tsx
// app/providers.tsx
"use client";
import { SessionProvider } from "next-auth/react";

export function Providers({ children }: { children: React.ReactNode }) {
  return <SessionProvider>{children}</SessionProvider>;
}
```

## Custom credentials

```ts
import Credentials from "next-auth/providers/credentials";
import { verifyPassword } from "@/lib/auth";

export const { handlers, auth } = NextAuth({
  providers: [
    Credentials({
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize({ email, password }) {
        const user = await db.user.findUnique({ where: { email } });
        if (!user || !(await verifyPassword(password, user.hashedPassword)))
          return null;
        return { id: user.id, name: user.name, email: user.email };
      },
    }),
  ],
});
```

## Role-based access

```ts
// Extend the session type
declare module "next-auth" {
  interface Session {
    user: { role: "admin" | "user" } & DefaultSession["user"];
  }
}

// In the JWT / session callbacks
callbacks: {
  jwt({ token, user }) {
    if (user) token.role = (user as any).role;
    return token;
  },
  session({ session, token }) {
    session.user.role = token.role as "admin" | "user";
    return session;
  },
}

// In a Server Component
const session = await auth();
if (session?.user.role !== "admin") redirect("/403");
```

