## Core Web Vitals — useReportWebVitals

Next.js ships a hook that fires standardised web vitals metrics as they're measured by the browser:

```tsx
// app/analytics.tsx
"use client";
import { useReportWebVitals } from "next/web-vitals";

export function WebVitalsReporter() {
  useReportWebVitals((metric) => {
    // metric.name: "LCP" | "CLS" | "INP" | "FID" | "TTFB" | "FCP"
    // metric.value: the raw number
    // metric.rating: "good" | "needs-improvement" | "poor"

    // Send to your analytics
    fetch("/api/vitals", {
      method: "POST",
      body: JSON.stringify(metric),
      headers: { "Content-Type": "application/json" },
    });

    // Or send to Google Analytics
    if (typeof window.gtag !== "undefined") {
      window.gtag("event", metric.name, {
        value: Math.round(metric.name === "CLS" ? metric.value * 1000 : metric.value),
        event_category: "Web Vitals",
        event_label: metric.id,
        non_interaction: true,
      });
    }
  });

  return null;
}

// app/layout.tsx — Server Component
import { WebVitalsReporter } from "./analytics";

export default function RootLayout({ children }) {
  return (
    <html>
      <body>
        {children}
        <WebVitalsReporter />
      </body>
    </html>
  );
}
```

## Third-party analytics scripts

Use `next/script` with the right strategy:

```tsx
// app/layout.tsx
import Script from "next/script";

export default function RootLayout({ children }) {
  return (
    <html>
      <body>
        {children}

        {/* GA4 */}
        <Script
          src={`https://www.googletagmanager.com/gtag/js?id=${process.env.NEXT_PUBLIC_GA_ID}`}
          strategy="afterInteractive"
        />
        <Script id="ga4-init" strategy="afterInteractive">
          {`
            window.dataLayer = window.dataLayer || [];
            function gtag(){dataLayer.push(arguments);}
            gtag('js', new Date());
            gtag('config', '${process.env.NEXT_PUBLIC_GA_ID}');
          `}
        </Script>

        {/* Plausible / PostHog / Segment — even simpler */}
        <Script
          defer
          data-domain="example.com"
          src="https://plausible.io/js/script.js"
          strategy="lazyOnload"
        />
      </body>
    </html>
  );
}
```

## Script strategies explained

| Strategy | When it loads | Use for |
| --- | --- | --- |
| `beforeInteractive` | Before hydration, blocks | Critical polyfills only |
| `afterInteractive` (default) | After hydration | Analytics that need early page data |
| `lazyOnload` | After `window.onload` | Chat widgets, social embeds |
| `worker` | Web Worker via Partytown | CPU-heavy third-party scripts |

For most analytics, `afterInteractive` is right — it fires after the LCP element has rendered.

## Page view tracking in App Router

The App Router doesn't fire a full page load on navigation — track page views by listening to pathname changes:

```tsx
"use client";
import { useEffect } from "react";
import { usePathname, useSearchParams } from "next/navigation";

export function PageViewTracker() {
  const pathname = usePathname();
  const searchParams = useSearchParams();

  useEffect(() => {
    const url = `${pathname}?${searchParams.toString()}`;
    // Fire your analytics page view here
    gtag("event", "page_view", { page_location: url });
  }, [pathname, searchParams]);

  return null;
}
```

Without this, client-side navigation between routes won't register as a new page view in most analytics tools.

## Consent-aware loading

```tsx
"use client";
import { useEffect, useState } from "react";
import Script from "next/script";

export function ConsentAwareAnalytics() {
  const [consented, setConsented] = useState(false);

  useEffect(() => {
    const stored = localStorage.getItem("analytics_consent");
    setConsented(stored === "true");
  }, []);

  if (!consented) return null;

  return (
    <Script
      src="https://plausible.io/js/script.js"
      strategy="afterInteractive"
    />
  );
}
```

Load analytics scripts only after the user has consented — legally required under GDPR for non-essential cookies.

