## The App Router approach with next-intl

### Folder structure

```
app/
├── [locale]/
│   ├── layout.tsx        ← locale-aware root layout
│   ├── page.tsx          → /en, /tr
│   ├── about/
│   │   └── page.tsx      → /en/about, /tr/about
│   └── blog/
│       └── [slug]/
│           └── page.tsx
messages/
├── en.json
└── tr.json
```

### Middleware for locale detection

```ts
// middleware.ts
import createMiddleware from "next-intl/middleware";

export default createMiddleware({
  locales: ["en", "tr"],
  defaultLocale: "en",
  localeDetection: true, // auto-detect from Accept-Language
});

export const config = {
  matcher: ["/((?!api|_next|_vercel|.*\\..*).*)"],
};
```

This rewrites `/about` → `/en/about` based on the browser's language preference, and strips the locale prefix from the URL for the default locale (configurable).

### Translation files

```json
// messages/en.json
{
  "HomePage": {
    "title": "Welcome to Acme",
    "description": "Enterprise software built for scale"
  },
  "Navigation": {
    "about": "About",
    "blog": "Blog"
  }
}
```

```json
// messages/tr.json
{
  "HomePage": {
    "title": "Acme'ye Hoş Geldiniz",
    "description": "Ölçek için üretilmiş kurumsal yazılım"
  },
  "Navigation": {
    "about": "Hakkında",
    "blog": "Blog"
  }
}
```

### Layout — loading translations server-side

```tsx
// app/[locale]/layout.tsx
import { NextIntlClientProvider } from "next-intl";
import { getMessages } from "next-intl/server";
import { notFound } from "next/navigation";

const locales = ["en", "tr"];

export default async function LocaleLayout({
  children,
  params,
}: {
  children: React.ReactNode;
  params: Promise<{ locale: string }>;
}) {
  const { locale } = await params;

  if (!locales.includes(locale)) notFound();

  const messages = await getMessages();

  return (
    <html lang={locale}>
      <body>
        <NextIntlClientProvider messages={messages}>
          {children}
        </NextIntlClientProvider>
      </body>
    </html>
  );
}
```

### Using translations in Server Components

```tsx
// app/[locale]/page.tsx
import { useTranslations } from "next-intl";

export default function HomePage() {
  const t = useTranslations("HomePage");

  return (
    <main>
      <h1>{t("title")}</h1>
      <p>{t("description")}</p>
    </main>
  );
}
```

The `t()` call happens on the server — zero translation strings ship in the client bundle.

### Localised navigation

```tsx
"use client";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useLocale } from "next-intl";

export function LocaleSwitcher() {
  const router = useRouter();
  const locale = useLocale();

  return (
    <div>
      <button
        className={locale === "en" ? "font-bold" : ""}
        onClick={() => router.replace("/", { locale: "en" })}
      >
        EN
      </button>
      <button
        className={locale === "tr" ? "font-bold" : ""}
        onClick={() => router.replace("/", { locale: "tr" })}
      >
        TR
      </button>
    </div>
  );
}
```

### Generating static paths for all locales

```tsx
// app/[locale]/blog/[slug]/page.tsx
export async function generateStaticParams() {
  const locales = ["en", "tr"];
  const posts = await getAllPosts();

  return locales.flatMap((locale) =>
    posts.map((post) => ({ locale, slug: post.slug })),
  );
}
```

## Pages Router — built-in i18n

Pages Router has i18n routing built in — configure it in `next.config.js` and the routing layer handles locale prefix automatically:

```js
// next.config.js
module.exports = {
  i18n: {
    locales: ["en", "tr"],
    defaultLocale: "en",
  },
};
```

Then use `useRouter().locale` to access the current locale. Pair with `next-i18next` for the translation layer.

